b.add(S5, 317, "numeric", "What is the printed 55–50 rule for asymptomatic severe AR?", "EF ≤55% or LVEDD ≥50%", ["EF ≤40% or LVEDD ≥70%", "EF ≥55% or LVEDD ≤50%", "EF ≤50% or gradient >60 mmHg"], "The asymptomatic-severe branch is labelled the 55–50 rule with EF ≤55% and LVEDD ≥50%.")
b.add(S5, 317, "match", "Match each acute-AR cause to its printed feature — 1) Aortic dissection 2) Infective endocarditis 3) Rupture sinus of Valsalva 4) Trauma … A) Right-heart failure B) Chest pain C) No feature printed D) No feature printed", "1-B, 2-C, 3-A, 4-D", ["1-A, 2-B, 3-C, 4-D", "1-B, 2-C, 3-D, 4-A", "1-C, 2-B, 3-A, 4-D"], "The causes tree prints aortic dissection with chest pain, infective endocarditis without a feature, rupture sinus of Valsalva with right-heart failure and trauma without a feature.")
b.add(S5, 317, "fillup", "Acute regurgitation gives the ventricle no time to adapt, so LVEDP and LAP rise; at an LAP above ______ the printed next event is acute pulmonary edema.", "25 mmHg", ["5 mmHg", "15 mmHg", "60 mmHg"], "The pathology arrow reads ↑LVEDP → LAP >25 mmHg → acute pulmonary edema → LV failure.")
b.add(S5, 317, "recall", "Which two feature bullets are printed for acute AR?", "A short, low-pitched early diastolic murmur with soft S1; and LV failure producing cardiogenic shock and hypotension", ["A long harsh ESM with loud S1; and systemic hypertension", "A mid-diastolic rumble with S4; and isolated right-heart failure", "A continuous murmur; and polycythemia"], "The feature bullets read short, low-pitched EDM with soft S1 and LVF → cardiogenic shock/hypotension.")
